using Daml.Runtime.Data;

namespace Daml.Runtime.Contracts;

/// <summary>
/// Helpers for projecting <see cref="TransactionResult.CreatedContracts"/> into typed
/// <see cref="ContractId{T}"/> values.
/// </summary>
/// <remarks>
/// These helpers bridge the (untyped) wire-level <see cref="CreatedContract"/> list
/// back to the C# marker types generated by <c>canton-dotnet-sdk</c>. When the marker
/// type is a template, a created contract matches when its <see cref="CreatedContract.PackageName"/>,
/// module and entity equal the marker's. The package id is not part of the match, so a template upgrade
/// that changes the package id but keeps the package name still resolves, and a same-named template of
/// another package never does. A contract that carries no package name matches no template marker. When
/// the marker is a Daml interface, it matches when the contract's <see cref="CreatedContract.InterfaceIds"/>
/// contains the marker's exact interface identifier, package id included: Daml interface definitions are
/// not upgradeable, so an interface keeps one package id for good. A transaction result carries interface
/// views only when its submission asked for them, as <c>CreateOneByExerciseAsync</c> and
/// <c>CreateManyByExerciseAsync</c> do for an interface; matching an interface against a result produced
/// without them throws <see cref="InvalidOperationException"/> rather than report that nothing matched.
/// </remarks>
public static class TransactionResultExtensions
{
    /// <summary>
    /// Returns the single created <see cref="ContractId{T}"/> matching <typeparamref name="T"/>'s
    /// identifier. Throws <see cref="InvalidOperationException"/> if zero or
    /// more than one contract of <typeparamref name="T"/> was created, or when <typeparamref name="T"/>
    /// is an interface the result was produced without interface data for.
    /// </summary>
    [System.Diagnostics.CodeAnalysis.SuppressMessage(
        "Naming", "CA1720:Identifier contains type name",
        Justification = "Mirrors Canton/Daml ledger API helper naming.")]
    public static ContractId<T> Single<T>(this TransactionResult result) where T : IDamlType
    {
        ArgumentNullException.ThrowIfNull(result);
        var matches = MatchingContractIds<T>(result);
        return matches.Count switch
        {
            1 => new ContractId<T>(matches[0]),
            0 => throw new InvalidOperationException(
                $"Transaction created no contracts of type {typeof(T).Name}."),
            _ => throw new InvalidOperationException(
                $"Transaction created {matches.Count} contracts of type {typeof(T).Name}, expected exactly 1."),
        };
    }

    /// <summary>
    /// Returns the single created <see cref="ContractId{T}"/> matching <typeparamref name="T"/>'s
    /// identifier, or <c>null</c> if none was created. Throws
    /// <see cref="InvalidOperationException"/> if more than one was created, or when
    /// <typeparamref name="T"/> is an interface the result was produced without interface data for.
    /// </summary>
    public static ContractId<T>? TrySingle<T>(this TransactionResult result) where T : IDamlType
    {
        ArgumentNullException.ThrowIfNull(result);
        var matches = MatchingContractIds<T>(result);
        return matches.Count switch
        {
            0 => null,
            1 => new ContractId<T>(matches[0]),
            _ => throw new InvalidOperationException(
                $"Transaction created {matches.Count} contracts of type {typeof(T).Name}, expected at most 1."),
        };
    }

    /// <summary>
    /// Returns all created <see cref="ContractId{T}"/> matching <typeparamref name="T"/>'s
    /// identifier, in transaction order. Carried as an
    /// <see cref="EquatableArray{T}">EquatableArray&lt;ContractId&lt;T&gt;&gt;</see>, like the
    /// <see cref="TransactionResult.CreatedContracts"/> it projects, so two calls over the
    /// same created contracts compare equal. Throws <see cref="InvalidOperationException"/> when
    /// <typeparamref name="T"/> is an interface the result was produced without interface data for.
    /// </summary>
    public static EquatableArray<ContractId<T>> All<T>(this TransactionResult result) where T : IDamlType
    {
        ArgumentNullException.ThrowIfNull(result);
        var matches = MatchingContractIds<T>(result);
        var ids = new ContractId<T>[matches.Count];
        for (var i = 0; i < matches.Count; i++)
        {
            ids[i] = new ContractId<T>(matches[i]);
        }
        return EquatableArray.Create(ids);
    }

    private static List<string> MatchingContractIds<T>(TransactionResult result) where T : IDamlType
    {
        var marker = T.DamlTypeId;
        ThrowIfInterfaceDataWasNotRequested(marker, result);
        var matches = new List<string>(result.CreatedContracts.Count);
        foreach (var created in result.CreatedContracts)
        {
            if (Matches(marker, created))
            {
                matches.Add(created.ContractId);
            }
        }
        return matches;
    }

    private static void ThrowIfInterfaceDataWasNotRequested(DamlTypeDescriptor marker, TransactionResult result)
    {
        if (marker.Kind == DamlTypeKind.Interface && !result.RequestedInterfaces.Contains(marker.Identifier))
        {
            throw new InvalidOperationException(
                $"This transaction result was produced without interface data for {marker.Identifier.EntityName}, " +
                "so no contract can be matched to it. Submit with CreateOneByExerciseAsync or " +
                "CreateManyByExerciseAsync for the interface, which request its views, or read the " +
                "contract through an interface-view query.");
        }
    }

    private static bool Matches(DamlTypeDescriptor marker, CreatedContract created) =>
        marker.Kind == DamlTypeKind.Interface
            ? created.InterfaceIds.Any(interfaceId => MarkerMatch.Interface(marker, interfaceId))
            : MarkerMatch.Template(marker, created.PackageName, created.TemplateId);
}
